import { defineStyles } from '@/utils/defineStyles'
import { Database, File, X } from 'lucide-react-native'
import { View, Text } from 'react-native'
import { colors, Theme, useTheme } from '@/theme'
import { UIBlockData } from '../UIBlock'

export const CodeChangeBlock = ({
	data,
	isCancelled
}: {
	data: UIBlockData
	isCancelled: boolean
}) => {
	const { theme } = useTheme()
	const Icon = data.uiType === 'file' ? File : Database
	return (
		<>
			{isCancelled ? (
				<X size={18} color={colors[theme].gray[400]} />
			) : (
				<Icon size={18} color={colors[theme].gray[500]} />
			)}
			<View style={styles.fileChangeTextContainer}>
				<Text
					style={[
						styles.fileChangeText(theme),
						isCancelled && { color: colors[theme].gray[400] }
					]}
				>
					{data.text}
				</Text>
				{data.subtext && data.uiType !== 'database' && (
					<Text style={styles.fileChangeSubtext(theme)}>{data.subtext}</Text>
				)}
			</View>
		</>
	)
}

const styles = defineStyles({
	fileChangeTextContainer: {
		flex: 1,
		gap: 4,
		justifyContent: 'center'
	},
	fileChangeText: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[600]
	}),
	fileChangeSubtext: (theme: Theme) => ({
		fontSize: 14,
		fontWeight: '500',
		color: colors[theme].gray[400]
	})
})
